type LocalKey = keyof typeof S;

function fmt(lang: Lang, key: LocalKey, vars?: Record<string, string | number>): string {
  let text = tx(S[key], lang);
  if (vars) text = text.replace(/\{(\w+)\}/g, (m, name: string) => (name in vars ? String(vars[name]) : m));
  return text;
}

// ---- presets ----------------------------------------------------------------------------------------------------------

interface PresetRecord {
  id: string;
  kind: string;
  body?: Record<string, unknown>;
  placement?: {
    default_mode?: string;
    real_orbit?: {
      primary_hint?: string;
      a_m?: number;
      e?: number;
      i_deg?: number;
    };
  };
  source_scene?: string;
}

let presetsPromise: Promise<Map<string, PresetRecord>> | null = null;

function loadPresets(): Promise<Map<string, PresetRecord>> {
  if (!presetsPromise) {
    presetsPromise = fetch(dataUrl('Catalogue/presets.json', import.meta.env.BASE_URL))
      .then(async (r) => {
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        const doc = (await r.json()) as { presets?: PresetRecord[] };
        return new Map((doc.presets ?? []).filter((p) => p.kind === 'body' && p.body).map((p) => [p.id, p]));
      })
      .catch((e: unknown) => {
        presetsPromise = null;
        throw e;
      });
  }
  return presetsPromise;
}

/** Only body presets with a body record can be placed. */
const BODY_PRESETS: PresetIndexEntry[] = CATALOG_INDEX.presets.filter((p) => p.kind === 'body' && p.addable && p.body);

const HOLE_CLASSES = new Set(['black_hole', 'agn']);

/** '' or ' N': the first number that makes the preset name free in both languages among the live bodies' names. */
function isNames(v: unknown): v is LocalizedText {
  return !!v && typeof v === 'object' && typeof (v as LocalizedText).en === 'string';
}

function freeSuffix(names: LocalizedText, taken: Set<string>): string {
  const free = (suffix: string) => !taken.has(tx(names, 'en') + suffix) && !taken.has(tx(names, 'ru') + suffix);
  if (free('')) return '';
  for (let i = 2; ; i++) if (free(` ${i}`)) return ` ${i}`;
}

const C = 299792458;

/** The preview colour, from the renderer's own look resolution for a stand-in of the preset body. */
function presetColor(entry: PresetIndexEntry, record: PresetRecord | undefined): string {
  const cls = entry.body?.cls ?? '';
  const raw = record?.body ?? {};
  const kind: EngineBody['kind'] =
    cls === 'black_hole' || cls === 'agn' || cls === 'neutron_star' || cls === 'pulsar'
      ? cls
      : cls === 'star' || cls === 'white_dwarf' || cls === 'brown_dwarf'
        ? cls === 'brown_dwarf'
          ? 'planet'
          : 'star'
        : 'planet';
  const spec = (raw.appearance ?? {}) as AppearanceSpec;
  const standIn = {
    kind,
    classTag: cls,
    mass: entry.body?.massKg ?? 0,
    effectiveTemperature: entry.body?.teffK ?? 0,
    appearanceProfile: '',
    appearanceSeed: typeof spec.seed === 'number' ? spec.seed : 0,
    ring: null,
  } as unknown as EngineBody;
  const [r, g, b] = lookColor(resolveLook(standIn, spec));
  return `rgb(${Math.round(r * 255)}, ${Math.round(g * 255)}, ${Math.round(b * 255)})`;
}

function matches(entry: PresetIndexEntry, q: string, lang: Lang): boolean {
  if (!q) return true;
  const hay = [
    tx(entry.name, lang),
    tx(entry.name, lang === 'en' ? 'ru' : 'en'),
    tx(entry.description, lang),
    entry.id,
    entry.body?.cls ?? '',
    classLabel(entry.body?.cls ?? '', lang),
    entry.body?.subclass ?? '',
    ...entry.tags,
  ]
    .join(' ')
    .toLowerCase();
  return q
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean)
    .every((w) => hay.includes(w));
}

/** A default primary: the selected body if it is live, else the most massive body. */
function defaultPrimary(bodies: EngineBody[], selected: EngineBody | null): EngineBody | null {
  if (selected) return selected;
  let best: EngineBody | null = null;
  for (const b of bodies) if (!best || b.mass > best.mass) best = b;
  return best;
}

/** A sensible starting distance (m): the catalogue orbit if its hinted primary is the chosen one, else by class. */
function defaultDistance(record: PresetRecord | undefined, entry: PresetIndexEntry, primary: EngineBody | null, bodies: EngineBody[]): number {
  const radius = entry.body?.radiusM ?? 0;
  const orbit = record?.placement?.real_orbit;
  if (primary && orbit?.a_m && orbit.a_m > 0 && orbit.primary_hint && primary.key === orbit.primary_hint) return orbit.a_m;
  if (!primary) return AU;
  const cls = entry.body?.cls ?? '';
  let d: number;
  if (cls === 'moon') d = Math.max(30 * primary.radius, 4e8);
  else if (
    primary.kind === 'star' ||
    primary.kind === 'black_hole' ||
    primary.kind === 'agn' ||
    primary.kind === 'neutron_star' ||
    primary.kind === 'pulsar'
  )
    d = cls === 'star' || HOLE_CLASSES.has(cls) ? 10 * AU : AU;
  else d = Math.max(50 * primary.radius, 1e9);
  d = Math.max(d, 20 * (primary.radius + radius), 50 * primary.schwarzschildRadius);
  // Beyond every body already orbiting this primary closer than that, so the new body does not land on one.
  for (const b of bodies) {
    if (b.id === primary.id) continue;
    const r = len(sub(b.position, primary.position));
    if (Math.abs(r - d) < 0.05 * d) d *= 1.3;
  }
  return d;
}

/** Position and velocity (SI): the primary's plus an offset in the ecliptic plane at angle th from +x, moving prograde. */
function place(primary: EngineBody | null, r: number, th: number, speed: number): { position: Vec3; velocity: Vec3 } | null {
  const p0: Vec3 = primary ? primary.position : [0, 0, 0];
  const v0: Vec3 = primary ? primary.velocity : [0, 0, 0];
  const position: Vec3 = [p0[0] + r * Math.cos(th), p0[1] + r * Math.sin(th), p0[2]];
  const velocity: Vec3 = [v0[0] - speed * Math.sin(th), v0[1] + speed * Math.cos(th), v0[2]];
  return position.every(Number.isFinite) && velocity.every(Number.isFinite) ? { position, velocity } : null;
}

// ---- the dialog -------------------------------------------------------------------------------------------------------

const MASS_RULE: FieldRule = { positive: true, max: 1e44 };
const RADIUS_RULE: FieldRule = { positive: true, max: 1e14 };
const DISTANCE_RULE: FieldRule = { positive: true, max: 1e20 };
const SPEED_RULE: FieldRule = { nonNegative: true, max: 0.999 * C };
const ANGLE_RULE: FieldRule = { min: -1e6, max: 1e6 };

type VelocityMode = 'circular' | 'manual';

export function AddBodyDialog({ presetId, onClose }: { presetId?: string; onClose: () => void }) {
  const t = useT();
  const lang = useLang();
  const system = useSetting('units');
  const L = (key: LocalKey, vars?: Record<string, string | number>) => fmt(lang, key, vars);
  const live = useStore(sessionStore, (s) => s.snapshot);
  const scene = useStore(sessionStore, (s) => s.scene);
  const appearance = useStore(sessionStore, (s) => s.appearance);
  const nameOf = (b: EngineBody) => bodyDisplayName(b, lang, scene, live, appearance);
  const selection = useStore(sessionStore, (s) => s.selection);
  const pending = useStore(sessionStore, (s) => s.pending);
  const titleId = useId();
  const dialogRef = useRef<HTMLDivElement>(null);
  const searchRef = useRef<HTMLInputElement>(null);

  const [records, setRecords] = useState<Map<string, PresetRecord> | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const [family, setFamily] = useState<string>('all');
  const [chosen, setChosen] = useState<string | null>(presetId && BODY_PRESETS.some((p) => p.id === presetId) ? presetId : null);

  useEffect(() => {
    let alive = true;
    loadPresets().then(
      (m) => alive && setRecords(m),
      (e: unknown) => alive && setLoadError(e instanceof Error ? e.message : String(e)),
    );
    return () => {
      alive = false;
    };
  }, []);

  // Focus the search first; Tab stays in the dialog; focus returns to the opener on close.
  useEffect(() => {
    const opener = document.activeElement as HTMLElement | null;
    searchRef.current?.focus();
    return () => opener?.focus?.();
  }, []);

  const families = useMemo(() => {
    const present = new Set(BODY_PRESETS.map((p) => String(p.family)));
    return PRESET_FAMILY_ORDER.filter((f) => present.has(f));
  }, []);

  const list = useMemo(
    () => BODY_PRESETS.filter((p) => (family === 'all' || p.family === family) && matches(p, query.trim(), lang)),
    [family, query, lang],
  );

  const colors = useMemo(() => new Map(BODY_PRESETS.map((p) => [p.id, presetColor(p, records?.get(p.id))])), [records]);
  const entry = chosen ? (BODY_PRESETS.find((p) => p.id === chosen) ?? null) : null;
  const record = entry && records ? records.get(entry.id) : undefined;

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    e.stopPropagation(); // typing here never reaches the page's global shortcuts
    if (e.key === 'Escape') {
      e.preventDefault();
      onClose();
      return;
    }
    if (e.key === 'Tab' && dialogRef.current) {
      const items = Array.from(
        dialogRef.current.querySelectorAll<HTMLElement>(
          'button:not(:disabled), input:not(:disabled), select:not(:disabled), [tabindex]:not([tabindex="-1"])',
        ),
      );
      if (items.length === 0) return;
      const first = items[0]!;
      const last = items[items.length - 1]!;
      if (e.shiftKey && document.activeElement === first) {
        e.preventDefault();
        last.focus();
      } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    }
  };

  const selected = bodyOf(selection, live);

  return createPortal(
    <div
      className="abDialog-backdrop"
      onMouseDown={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div ref={dialogRef} className="abDialog" role="dialog" aria-modal="true" aria-labelledby={titleId} onKeyDown={onKeyDown}>
        <header className="abDialog-head">
          <h2 id={titleId}>{L('title')}</h2>
          <button type="button" className="icon-btn" onClick={onClose} aria-label={t('common.close')} title={t('common.close')}>
            <Icon name="close" size={18} />
          </button>
        </header>
        <div className="abDialog-body">
          <aside className="ab-picker" aria-label={L('search')}>
            <label className="ab-search">
              <Icon name="search" size={16} />
              <input
                ref={searchRef}
                type="search"
                value={query}
                placeholder={L('searchPlaceholder')}
                aria-label={L('search')}
                onChange={(e) => setQuery(e.target.value)}
              />
            </label>
            <div className="ab-families" role="group" aria-label={L('search')}>
              <button
                type="button"
                className={'ab-chip' + (family === 'all' ? ' active' : '')}
                aria-pressed={family === 'all'}
                onClick={() => setFamily('all')}
              >
                {L('all')}
              </button>
              {families.map((f) => (
                <button
                  key={f}
                  type="button"
                  className={'ab-chip' + (family === f ? ' active' : '')}
                  aria-pressed={family === f}
                  onClick={() => setFamily(f)}
                >
                  {tx(CATALOG_INDEX.labels.presetFamilies[f], lang) || f}
                </button>
              ))}
            </div>
            <p className="ab-count">{L('presetsCount', { n: list.length })}</p>
            <ul className="ab-list" aria-label={L('presetsCount', { n: list.length })}>
              {list.map((p) => (
                <li key={p.id}>
                  <button
                    type="button"
                    className={'ab-item' + (chosen === p.id ? ' active' : '')}
                    aria-pressed={chosen === p.id}
                    onClick={() => setChosen(p.id)}
                  >
                    <span className="ab-dot" style={{ background: colors.get(p.id) }} aria-hidden="true" />
                    <span className="ab-item-text">
                      <span className="ab-item-name">{tx(p.name, lang)}</span>
                      <span className="ab-item-sub">
                        {classLabel(p.body?.cls ?? '', lang)}
                        {p.body?.massKg ? ` · ${formatQuantity('mass', p.body.massKg, lang, system, 3)}` : ''}
                      </span>
                    </span>
                  </button>
                </li>
              ))}
              {list.length === 0 && <li className="ab-none">{L('none', { q: query })}</li>}
            </ul>
            <p className="ab-note">{L('catalogueOnly')}</p>
          </aside>
          <section className="ab-form-pane">
            {!live ? (
              <p className="ab-empty">{L('noWorld')}</p>
            ) : loadError ? (
              <p className="ab-error" role="alert">
                {L('loadFailed', { reason: loadError })}
              </p>
            ) : !entry ? (
              <p className="ab-empty">{L('pick')}</p>
            ) : !record ? (
              <p className="ab-empty">{L('loading')}</p>
            ) : (
              <PlacementForm
                key={`${entry.id}|${live.worldId}`}
                entry={entry}
                record={record}
                bodies={live.bodies}
                selected={selected}
                disabled={!!pending}
                onDone={onClose}
                nameOf={nameOf}
              />
            )}
          </section>
        </div>
      </div>
    </div>,
    document.body,
  );
}

function PlacementForm({
  entry,
  record,
  bodies,
  selected,
  disabled,
  onDone,
  nameOf,
}: {
  entry: PresetIndexEntry;
  record: PresetRecord;
  bodies: EngineBody[];
  selected: EngineBody | null;
  disabled: boolean;
  onDone: () => void;
  nameOf: (b: EngineBody) => string;
}) {
  const t = useT();
  const lang = useLang();
  const system = useSetting('units');
  const L = (key: LocalKey, vars?: Record<string, string | number>) => fmt(lang, key, vars);
  const formId = useId();
  const playing = useStore(sessionStore, (s) => !!s.snapshot?.playing);
  const body0 = record.body!;
  const cls = String(body0.class ?? entry.body?.cls ?? '');
  const hole = HOLE_CLASSES.has(cls);
  const massSi0 = typeof body0.gm_m3_s2 === 'number' && body0.gm_m3_s2 > 0 ? body0.gm_m3_s2 / G : Number(body0.mass_kg);
  const radiusSi0 = Number(body0.radius_m);

  const [primaryId, setPrimaryId] = useState<number>(() => defaultPrimary(bodies, selected)?.id ?? 0);
  const primary = bodies.find((b) => b.id === primaryId) ?? null;
  const primaryName = primary ? nameOf(primary) : '';
  // Suggested once per chosen primary (not per playback frame), from the bodies at that moment.
  const [startDistance] = useState(() => defaultDistance(record, entry, primary, bodies));

  const [units, setUnits] = useState(() => ({
    mass: autoUnit('mass', massSi0, system).id,
    radius: autoUnit('radius', radiusSi0, system).id,
    distance: autoUnit('distance', startDistance, system).id,
    speed: autoUnit('velocity', 3e4, system).id,
  }));
  // The suggested name: the preset's, numbered when a live body already has it (in either language).
  const presetNames = (isNames(body0.name) ? body0.name : entry.name) as LocalizedText;
  const [suffix] = useState(() => freeSuffix(presetNames, new Set(bodies.flatMap((b) => [b.name, nameOf(b)]))));
  const [name, setName] = useState(() => tx(presetNames, lang) + suffix);
  const [mass, setMass] = useState(() => inputText(massSi0 / unitById('mass', units.mass).factor, 9));
  const [radius, setRadius] = useState(() => inputText(radiusSi0 / unitById('radius', units.radius).factor, 9));
  const [distance, setDistance] = useState(() => inputText(startDistance / unitById('distance', units.distance).factor, 6));
  const [distanceTouched, setDistanceTouched] = useState(false);
  const [angle, setAngle] = useState('0');
  const [mode, setMode] = useState<VelocityMode>('circular');
  const [speed, setSpeed] = useState('');
  const [touched, setTouched] = useState({ mass: false, radius: false });
  const [formError, setFormError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  // A new primary suggests a new distance until the user typed one; without a primary the speed is always chosen.
  const choosePrimary = (id: number) => {
    setPrimaryId(id);
    const next = bodies.find((b) => b.id === id) ?? null;
    if (!distanceTouched) {
      const d = defaultDistance(record, entry, next, bodies);
      const u = autoUnit('distance', d, system);
      setUnits((x) => ({ ...x, distance: u.id }));
      setDistance(inputText(d / u.factor, 6));
    }
    if (!next && !speed.trim()) setSpeed('0');
  };

  const changeUnit = (field: 'mass' | 'radius' | 'distance' | 'speed', next: string) => {
    const q: Quantity = field === 'speed' ? 'velocity' : field;
    const from = unitById(q, units[field]).factor;
    const to = unitById(q, next).factor;
    const conv = (s: string) => {
      const r = validateField(s, from, {}, t);
      return r.value === null ? s : inputText(r.value / to, 9);
    };
    if (field === 'mass') setMass(conv(mass));
    if (field === 'radius') setRadius(conv(radius));
    if (field === 'distance') setDistance(conv(distance));
    if (field === 'speed') setSpeed(conv(speed));
    setUnits({ ...units, [field]: next });
  };

  const massR = validateField(mass, unitById('mass', units.mass).factor, MASS_RULE, t);
  // A hole's radius is its Schwarzschild radius 2GM/c², so it follows the mass.
  const radiusR = hole
    ? { value: massR.value !== null ? (2 * G * massR.value) / (C * C) : null, error: null }
    : validateField(radius, unitById('radius', units.radius).factor, RADIUS_RULE, t);
  const distR = validateField(distance, unitById('distance', units.distance).factor, DISTANCE_RULE, t);
  const angleR = validateField(angle, Math.PI / 180, ANGLE_RULE, t);
  const vCirc = primary && massR.value && distR.value ? circularSpeed(primary.mass, massR.value, distR.value) : null;
  const manual = mode === 'manual' || !primary;
  const speedR = manual ? validateField(speed, unitById('velocity', units.speed).factor, SPEED_RULE, t) : { value: vCirc ?? 0, error: null };
  const nameError = name.trim() ? null : t('field.required');
  // Touching the primary (centre distance within the sum of radii) is an overlap the engine refuses anyway.
  const contact = primary ? primary.radius + (radiusR.value ?? 0) : 0;
  const inside = primary && distR.value !== null && distR.value <= contact;
  const insideText = primary ? L('inside', { name: primaryName, min: formatQuantity('distance', contact, lang, system) }) : '';

  const placement =
    distR.value !== null && angleR.value !== null && speedR.value !== null ? place(primary, distR.value, angleR.value, speedR.value) : null;

  // The nearest other body to the placed position (a hint; the engine decides overlap).
  let nearest: { body: EngineBody; d: number } | null = null;
  for (const b of placement ? bodies : []) {
    const d = len(sub(b.position, placement!.position));
    if (!nearest || d < nearest.d) nearest = { body: b, d };
  }
  const tooClose = nearest && radiusR.value !== null && nearest.d < 5 * (nearest.body.radius + radiusR.value);

  const invalid = !!(nameError || massR.error || radiusR.error || distR.error || angleR.error || speedR.error || inside || !placement);

  const submit = async () => {
    setFormError(null);
    if (invalid || !placement || massR.value === null || radiusR.value === null || distR.value === null || angleR.value === null) {
      setFormError(inside ? insideText : L('fixFields'));
      return;
    }
    setBusy(true);
    // The primary moves while the world plays: stop first, then place against its stopped state.
    const worldId = sessionStore.get().snapshot?.worldId;
    if (sessionStore.get().snapshot?.playing) await pause();
    const snap = sessionStore.get().snapshot;
    const now = primary ? (snap?.bodies.find((b) => b.id === primary.id) ?? null) : null;
    const v = manual ? speedR.value : now ? circularSpeed(now.mass, massR.value, distR.value) : null;
    const state =
      snap && !snap.playing && snap.worldId === worldId && (!primary || now) && v !== null ? place(now, distR.value, angleR.value, v) : null;
    if (!state) {
      setBusy(false);
      setFormError(t('error.stale'));
      return;
    }
    // An immutable clone of the catalogue record: every scene-body attribute is kept; only identity, name, mass, radius
    // and state are set here.
    const body = JSON.parse(JSON.stringify(body0)) as Record<string, unknown>;
    const key = uniqueKey(String(body0.id ?? entry.id));
    body.id = key;
    const typed = name.trim();
    // The suggested name keeps both languages; a name the player typed is used as is in both.
    const suggested = typed === tx(presetNames, 'en') + suffix || typed === tx(presetNames, 'ru') + suffix;
    const names: LocalizedText = suggested ? { en: tx(presetNames, 'en') + suffix, ru: tx(presetNames, 'ru') + suffix } : { en: typed, ru: typed };
    body.name = names;
    // GM is the core's primary mass input; a changed mass must replace it (else the catalogue GM would win).
    if (touched.mass && massR.value !== massSi0) {
      body.mass_kg = massR.value;
      delete body.gm_m3_s2;
    }
    if (hole ? touched.mass && massR.value !== massSi0 : touched.radius && radiusR.value !== radiusSi0) body.radius_m = radiusR.value;
    body.position_m = state.position;
    body.velocity_mps = state.velocity;
    // The hierarchy link (the bridge resolves it to the first live body with that key), only when the key is unambiguous.
    if (now && now.key && (snap?.bodies.filter((b) => b.key === now.key).length ?? 0) === 1) body.parent = now.key;
    else delete body.parent;
    const look: AppearanceSpec = {
      ...((body0.appearance ?? {}) as AppearanceSpec),
    };
    if (body0.compact && typeof body0.compact === 'object') look.compact = body0.compact as Record<string, unknown>;
    // The engine keeps the English name only; the look carries both so bodyDisplayName can localize an untouched name.
    if (suggested) look.names = names;
    const ids = await addBodies([body as SceneBodyJson], { [key]: look }, L('addLabel', { name: typed }));
    setBusy(false);
    if (ids && ids.length > 0) onDone();
    else setFormError(L('refused'));
  };

  const desc = tx(entry.description, lang);
  const summary = entry.body;
  return (
    <form
      className="ab-form"
      noValidate
      onSubmit={(e) => {
        e.preventDefault();
        void submit();
      }}
    >
      <fieldset className="ab-fields" disabled={disabled || busy}>
        <div className="ab-preview">
          <span
            className="ab-swatch"
            style={{
              background: presetColor(entry, record),
              boxShadow: `0 0 18px ${presetColor(entry, record)}`,
            }}
            aria-hidden="true"
          />
          <div className="ab-preview-text">
            <div className="ab-preview-name">{tx(entry.name, lang)}</div>
            <div className="ab-preview-kind">
              {classLabel(cls, lang)}
              {summary?.subclass ? ` · ${classLabel(summary.subclass, lang, 'subclass')}` : ''}
              {summary?.teffK ? ` · ${formatNumber(summary.teffK, lang, 4)} K` : ''}
            </div>
            {desc && <p className="ab-preview-desc">{desc}</p>}
            <p className="ab-preview-src">{record.source_scene ? L('source', { scene: record.source_scene }) : L('authored')}</p>
          </div>
        </div>

        <div className={'qfield' + (nameError ? ' invalid' : '')}>
          <label htmlFor={formId + '-name'}>{L('name')}</label>
          <input
            id={formId + '-name'}
            className="input"
            value={name}
            maxLength={80}
            disabled={disabled || busy}
            aria-invalid={!!nameError}
            onChange={(e) => setName(e.target.value)}
          />
          {nameError && <span className="qfield-error">{nameError}</span>}
        </div>
        <div className="ab-pair">
          <QuantityField
            label={L('mass')}
            quantity="mass"
            unit={units.mass}
            onUnit={(u) => changeUnit('mass', u)}
            text={mass}
            onText={(s) => {
              setMass(s);
              setTouched((x) => ({ ...x, mass: true }));
            }}
            error={massR.error}
            lang={lang}
            disabled={disabled || busy}
          />
          <QuantityField
            label={L('radius')}
            quantity="radius"
            unit={units.radius}
            onUnit={(u) => changeUnit('radius', u)}
            text={hole ? (radiusR.value !== null ? inputText(radiusR.value / unitById('radius', units.radius).factor, 9) : '') : radius}
            onText={(s) => {
              setRadius(s);
              setTouched((x) => ({ ...x, radius: true }));
            }}
            error={radiusR.error}
            lang={lang}
            disabled={disabled || busy || hole}
            hint={hole ? L('holeRadius') : undefined}
          />
        </div>

        <div className="qfield">
          <label htmlFor={formId + '-primary'}>{L('primary')}</label>
          <select
            id={formId + '-primary'}
            className="input"
            value={primaryId}
            disabled={disabled || busy}
            onChange={(e) => choosePrimary(Number(e.target.value))}
          >
            {[...bodies]
              .sort((a, b) => b.mass - a.mass)
              .map((b) => (
                <option key={b.id} value={b.id}>
                  {nameOf(b) + ' — ' + classLabel(b.classTag || b.kind, lang)}
                </option>
              ))}
            <option value={0}>{L('noPrimary')}</option>
          </select>
        </div>
        <div className="ab-pair">
          <QuantityField
            label={primary ? L('distance') : L('distanceFree')}
            quantity="distance"
            unit={units.distance}
            onUnit={(u) => changeUnit('distance', u)}
            text={distance}
            onText={(s) => {
              setDistance(s);
              setDistanceTouched(true);
            }}
            error={distR.error ?? (inside ? insideText : null)}
            lang={lang}
            disabled={disabled || busy}
            units={['km', 'au', 'ly', 'm']}
          />
          <QuantityField
            label={L('angle')}
            quantity="angle"
            unit="deg"
            onUnit={() => undefined}
            text={angle}
            onText={setAngle}
            error={angleR.error}
            lang={lang}
            disabled={disabled || busy}
          />
        </div>

        <div className="ab-velocity">
          <span className="ab-label">{L('velocityMode')}</span>
          <Segmented<VelocityMode>
            value={manual ? 'manual' : 'circular'}
            onChange={(m) => {
              setMode(m);
              if (m === 'manual' && !speed && vCirc) {
                const u = autoUnit('velocity', vCirc, system);
                setUnits((x) => ({ ...x, speed: u.id }));
                setSpeed(inputText(vCirc / u.factor, 6));
              }
            }}
            options={[
              { value: 'circular', label: L('circular') },
              { value: 'manual', label: L('manual') },
            ]}
            size="sm"
            ariaLabel={L('velocityMode')}
          />
          {manual && (
            <QuantityField
              label={primary ? L('speed') : L('speedFree')}
              quantity="velocity"
              unit={units.speed}
              onUnit={(u) => changeUnit('speed', u)}
              text={speed}
              onText={setSpeed}
              error={speedR.error}
              lang={lang}
              disabled={disabled || busy}
            />
          )}
        </div>

        <div className="ab-result" aria-live="polite">
          {placement && (
            <p>
              {primary
                ? L('resultSpeed', {
                    primary: primaryName,
                    speed: formatQuantity('velocity', speedR.value ?? 0, lang, system),
                  })
                : L('resultFree', {
                    speed: formatQuantity('velocity', speedR.value ?? 0, lang, system),
                  })}
              {primary && vCirc && manual ? ` (${L('resultCircular', { speed: formatQuantity('velocity', vCirc, lang, system) })})` : ''}
            </p>
          )}
          {tooClose && nearest && (
            <p className="ab-warn">
              {L('tooClose', {
                name: nameOf(nearest.body),
                distance: formatQuantity('distance', nearest.d, lang, system),
              })}
            </p>
          )}
          <p className="ab-note">{L('assumption')}</p>
          {playing && <p className="ab-note">{L('pausesPlay')}</p>}
        </div>
      </fieldset>
      {formError && (
        <p className="ab-error" role="alert">
          {formError}
        </p>
      )}
      <footer className="ab-foot">
        <button type="submit" className="ab-btn ab-btn-primary" disabled={disabled || busy || invalid}>
          <Icon name="plus" size={16} />
          <span>{busy ? L('adding') : L('add')}</span>
        </button>
      </footer>
    </form>
  );
}

export default AddBodyDialog;
